steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "{
      teams(name: \"Mobile\") {
        nodes {
          id
          name
        }
      }
      users(search: \"Priya Nair\") {
        nodes {
          id
          name
          email
        }
      }
      workflowStates(name: \"In Review\") {
        nodes {
          id
          name
          type
        }
      }
    }
  }'
